#ifndef MOD_QCDLOOP_C
#define MOD_QCDLOOP_C

#include <complex>

// C++ declarations for the QCDLoop C-bound entry points that
// software/mcfm/src/Mods/mod_qcdloop_c.f exposes to Fortran via
// `bind(C, name=...)`. These functions are implemented outside this
// translation effort (the bundled QCDLoop library); this header lets
// translated C++ call them directly instead of going through the
// Fortran interface block.
//
// mod_qcdloop_c.f itself is left in place (unchanged) because other
// not-yet-translated Fortran callers still `use mod_qcdloop_c` to
// reach these same symbols.

extern "C" {
  void qlcachesize(int const& csize);

  std::complex<double> cln(std::complex<double> const& x, double const& isig);

  bool qlzero(double const& x);
  bool qlnonzero(double const& x);

  std::complex<double> qli1(double const& m1, double const& mu2, int const& ep);
  std::complex<double> qli1c(std::complex<double> const& m1, double const& mu2, int const& ep);

  std::complex<double> qli2(double const& p1, double const& m1, double const& m2, double const& mu2, int const& ep);
  std::complex<double> qli2c(double const& p1, std::complex<double> const& m1, std::complex<double> const& m2, double const& mu2, int const& ep);

  std::complex<double> qli2p(double const& p1, double const& m1, double const& m2, double const& mu2, int const& ep);
  std::complex<double> qli2pc(double const& p1, std::complex<double> const& m1, std::complex<double> const& m2, double const& mu2, int const& ep);

  std::complex<double> qli3(double const& p1, double const& p2, double const& p3, double const& m1, double const& m2, double const& m3, double const& mu2, int const& ep);
  std::complex<double> qli3c(double const& p1, double const& p2, double const& p3, std::complex<double> const& m1, std::complex<double> const& m2, std::complex<double> const& m3, double const& mu2, int const& ep);

  std::complex<double> qli4(double const& p1, double const& p2, double const& p3, double const& p4, double const& s12, double const& s23, double const& m1, double const& m2, double const& m3, double const& m4, double const& mu2, int const& ep);
  std::complex<double> qli4c(double const& p1, double const& p2, double const& p3, double const& p4, double const& s12, double const& s23, std::complex<double> const& m1, std::complex<double> const& m2, std::complex<double> const& m3, std::complex<double> const& m4, double const& mu2, int const& ep);

  // I consider the quad precision interface to be broken:
  // it probably only works with gfortran since there are no
  // standard c bindings for quad precision types
  // (on gfortran there is c_float128 and c_float128_complex)
  // fortran2008 defines real128, but that is still no interface type
  __float128 qli1q(__float128 const& m1, __float128 const& mu2, int const& ep);
  __float128 qli2q(__float128 const& p1, __float128 const& m1, __float128 const& m2, __float128 const& mu2, int const& ep);
  __float128 qli3q(__float128 const& p1, __float128 const& p2, __float128 const& p3, __float128 const& m1, __float128 const& m2, __float128 const& m3, __float128 const& mu2, int const& ep);
  __float128 qli4q(__float128 const& p1, __float128 const& p2, __float128 const& p3, __float128 const& p4, __float128 const& s12, __float128 const& s23, __float128 const& m1, __float128 const& m2, __float128 const& m3, __float128 const& m4, __float128 const& mu2, int const& ep);

  std::complex<__float128> qli1qc(std::complex<__float128> const& m1, __float128 const& mu2, int const& ep);
  std::complex<__float128> qli2qc(__float128 const& p1, std::complex<__float128> const& m1, std::complex<__float128> const& m2, __float128 const& mu2, int const& ep);
  std::complex<__float128> qli3qc(__float128 const& p1, __float128 const& p2, __float128 const& p3, std::complex<__float128> const& m1, std::complex<__float128> const& m2, std::complex<__float128> const& m3, __float128 const& mu2, int const& ep);
  std::complex<__float128> qli4qc(__float128 const& p1, __float128 const& p2, __float128 const& p3, __float128 const& p4, __float128 const& s12, __float128 const& s23, std::complex<__float128> const& m1, std::complex<__float128> const& m2, std::complex<__float128> const& m3, std::complex<__float128> const& m4, __float128 const& mu2, int const& ep);
}

#endif

